// Compact paraphrases of Revised chapter 4; complete systems stay in the linked book.
const book='https://wod.su/vampire/book/vampire_masquerade/04';
const entries={
  'Доминирование': {bookName:'Доминирование',text:'Подчинение мыслей. Нужны взгляд и понятная речь.',powers:[['Приказ','Однословная команда.'],['Гипноз','Внедрение сложного указания.']]},
  'Анимализм': {bookName:'Анимализм',text:'Общение с животными.',powers:[['Шепоты Зверя','Контакт и простые команды.']]},
  'Превращение': {bookName:'Превращение',text:'Изменение тела.',powers:[['Глаза Зверя','Зрение в темноте.'],['Когти Зверя','Когти наносят агравированный урон.'],['Слияние с Землей','Укрытие в почве.']]},
  'Стремительность': {bookName:'Стремительность',text:'Сверхъестественная скорость. За 1 пункт крови — дополнительные физические действия на следующем ходу: по одному за точку.',powers:[]},
  'Мощь': {bookName:'Могущество',text:'Сверхсила: точка добавляет автоуспех в проверках Силы и ближнем уроне.',powers:[]},
  'Величие': {bookName:'Присутствие',text:'Влияние на эмоции.',powers:[['Благоговение','Привлечение внимания и симпатии.'],['Взгляд Ужаса','Внушение страха.']]},
  'Прорицание': {bookName:'Прорицание',text:'Сверхчувственное восприятие.',powers:[['Обостренные Чувства','Усиление чувств.'],['Восприятие Ауры','Распознавание эмоций и сверхъестественного.']]},
  'Власть над Тенью': {bookName:'Власть над Тенью',text:'Управление тьмой.',powers:[['Игра Теней','Изменение теней.'],['Покров Ночи','Облако непроницаемой тьмы.'],['Руки Бездны','Цепкие теневые щупальца.']]},
  'Сокрытие': {bookName:'Затемнение',text:'Обман восприятия наблюдателей.',powers:[['Покров Тени','Неподвижность в укрытии.'],['Незримое Присутствие','Незаметное передвижение.'],['Маска Тысячи Лиц','Изменение воспринимаемой внешности.']]},
  'Тауматургия': {bookName:'Тауматургия',text:'Магия крови: пути и ритуалы. Конкретный путь в листе не указан; согласуйте с ведущим.',powers:[]}
};
export function disciplineReference(name,value) {
  const ref=entries[name==='Ясновидение'?'Прорицание':name];
  if(!ref)return null;
  return {...ref,name,value,powers:ref.powers.slice(0,value).map(([title,text],i)=>({level:i+1,title,text})),url:`${book}#:~:text=${encodeURIComponent(ref.bookName)}`};
}
